#!/usr/bin/env bash
# Inscriptions aux cours — ÉCRANS.
# - création d'un compte : « Cours suivis » ; un cours pour enfants/ados pré-coche « Mineur » (avertissement si Majeur) ;
# - fiche d'un membre : « Cours suivis », enregistrables ;
# - guides admin ; e2e (deux créneaux de test, inscriptions-cours.spec.ts). Pas de migration.
# Prérequis : apply-inscriptions-cours-backend.sh.
# Usage (racine du repo) : bash apply-inscriptions-cours-ecrans.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null | grep -qF "CoursesControl"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "model CourseEnrollment" "prisma/schema.prisma" 2>/dev/null || { echo "lancez d'abord apply-inscriptions-cours-backend.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/creer-un-utilisateur.mdx" "apps/web/content/docs/admin/gerer-un-membre.mdx" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/app/(admin)/dashboard/users/create/page.tsx" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "e2e/data.mjs" "e2e/prepare.mjs")
CREATED=("apps/web/src/features/admin/users/courses/CoursesControl.tsx" "apps/web/src/features/admin/users/courses/CoursesPicker.tsx" "e2e/inscriptions-cours.spec.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/features/admin/users/courses" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "CoursesControl" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/courses"
